$(document).ready(function(){$("a").on("click",function(e){if(""!==this.hash){e.preventDefault();var i=this.hash;$("html, body").animate({scrollTop:$(i).offset().top},1e3,function(){window.location.hash=i})}}),$(".homepageSlider").slick({arrows:!1,autoplay:!0,autoplaySpeed:2e3,dots:!1,infinite:!0}),$(".testimonial-slider").slick({arrows:!1,autoplay:!0,autoplaySpeed:3e3,dots:!1,infinite:!0,slidesToShow:2,slidesToScroll:1}),Galleria.loadTheme("lib/resource/ui/plugin/galleria/themes/classic/galleria.classic.min.js"),Galleria.run(".galleria"),$("#mobileMenu").click(function(e){e.preventDefault(),$(".mobileMenu").show()}),$("#closeMenu").click(function(e){e.preventDefault(),$(".mobileMenu").hide()})});